    tip1: '“মেসেজ যাচাই করুন”-এ যেকোনো মেসেজ লিখুন। রায়, শব্দের দাগ আর ধাপে ধাপে অঙ্ক লেখার সঙ্গে সঙ্গে বদলায়।',
    tip2: '“ধাপে ধাপে: অঙ্ক” খুলুন আর “ভেতরে উঁকি দিন”-এর গোনা দিয়ে একটি ভগ্নাংশ হাতে মিলিয়ে দেখুন। এটি CBSE ক্লাস 10 AI-এর evaluation অধ্যায় আর ক্লাস 11–12-এর Naive Bayes বিষয়ের সঙ্গে মেলে।',
    tip3: 'ক্লাসের কাজ: দুটি দল। দল A এমন 5টি আসল মেসেজ লিখবে যা ফিল্টার স্প্যাম বলে; দল B এমন 5টি স্প্যাম লিখবে যা ফসকে যায়। এগুলো ট্রেনিং মেসেজে যোগ করুন আর দেখুন কোন দলের কৌশল আর কাজ করে না।',
    tip4: 'ন্যায্য টেস্ট বন্ধ আর চালু করুন। আলোচনা করুন, ট্রেনিং মেসেজেই টেস্ট করলে স্কোর কেন বেশি ভালো আসে।',
    tip5: 'মেসেজগুলো CSV-তে ডাউনলোড করুন, ছাত্ররা বাড়িতে 20টি নতুন মেসেজে লেবেল দিক, পরের ক্লাসে সেগুলো আনুন। কিছুই আপলোড হয় না: সব এই ডিভাইসেই থাকে।',
