    step_words: 'પગલું 2 · દરેક શબ્દ માટે: તે સ્પામ સંદેશમાં કેટલો આવે છે, અને સાચામાં કેટલો? અમે દરેક ગણતરીમાં 1 ઉમેરીએ છીએ (Laplace smoothing), જેથી એક વર્ગમાં ન દેખાયેલો શબ્દ આખા ગુણાકારને શૂન્ય ન કરી દે.',
