    inside_t: 'અંદર શું થઈ રહ્યું છે?',
    in1_t: 'તે ફક્ત શબ્દો ગણે છે',
    in1: 'તાલીમ એટલે ગણતરી: દરેક શબ્દ સ્પામ સંદેશામાં કેટલી વાર આવે છે, અને સાચામાં કેટલી વાર? “લોટરી” સ્પામમાં જમા થાય છે, “હોમવર્ક” સાચામાં.',
    in2_t: 'Bayes નો નિયમ',
    in2: 'નવા સંદેશ માટે તે દરેક વર્ગની શરૂઆતની શક્યતાને તે વર્ગમાં દરેક શબ્દની શક્યતાથી ગુણે છે. જેનું પરિણામ મોટું, તે જીતે. આ જ Naive Bayes છે, પહેલા ઈમેલ સ્પામ ફિલ્ટરની પદ્ધતિ.',
    formula: 'P(સ્પામ | સંદેશ) ∝ P(સ્પામ) × P(શબ્દ₁ | સ્પામ) × P(શબ્દ₂ | સ્પામ) × …',
    in3_t: 'Laplace smoothing: +1 ની યુક્તિ',
    in3: 'જો કોઈ શબ્દ એક વર્ગમાં ક્યારેય ન દેખાયો હોય, તો તેની શક્યતા 0 થાય અને આખો ગુણાકાર 0 થઈ જાય. દરેક ગણતરીમાં 1 ઉમેરવાથી (અને અપૂર્ણાંકના નીચે V ઉમેરવાથી) દરેક શક્યતા શૂન્યથી થોડી ઉપર રહે છે.',
    in4_t: 'લૉગ કેમ?',
    in4: '0.003 જેવી વીસ સંખ્યાઓનો ગુણાકાર કરો તો 0.000000000000000000000000000001 જેવું કંઈક મળે. કમ્પ્યુટર આટલી નાની સંખ્યાઓ ગુમાવી દે છે, એટલે સાચા ફિલ્ટર log મૂલ્યો ઉમેરે છે. જીતનાર એ જ રહે છે.',
    in5_t: '“Naive” (ભોળું) કેમ?',
    in5: 'તે દરેક શબ્દને અલગ ગણે છે અને ક્રમ કે અર્થ જોતું નથી. “મૅચ જીત્યા” અને “લોટરી જીત્યા” બંનેમાં ફક્ત “જીત” છે. એટલે ગૂંચવતો સંદેશ તેને છેતરે છે, અને જુદાં જુદાં ઉદાહરણો મદદ કરે છે.',
    in6_t: 'સાચા સ્પામ ફિલ્ટર',
    in6: 'Gmail અને WhatsApp આ જ વિચાર અને ઘણું વધારે વાપરે છે: મોકલનારનો ઇતિહાસ, લિંક, ચિત્રો અને મોટા ન્યુરલ નેટવર્ક. પણ પાઠ એ જ: ફિલ્ટર એટલું જ સારું જેટલાં તેના શીખવાનાં ઉદાહરણો.',

    help_t: 'કેવી રીતે વાપરવું · વર્ગ માટે વિચારો',
    tip1: '“સંદેશ તપાસો” માં કોઈ પણ સંદેશ લખો. નિર્ણય, શબ્દોની પટ્ટીઓ અને પગલે પગલે ગણિત લખતાં લખતાં બદલાય છે.',
    tip2: '“પગલે પગલે: ગણિત” ખોલો અને “અંદર ડોકિયું” ની ગણતરીથી એક અપૂર્ણાંક હાથે તપાસો. આ CBSE ધોરણ 10 AI ના evaluation એકમ અને ધોરણ 11–12 ના Naive Bayes વિષય સાથે મેળ ખાય છે.',
