    spam_word: 'ஸ்பேம்',
    empty_msg: 'வடிகட்டி என்ன நினைக்கிறது என்று பார்க்க மேலே ஒரு செய்தியை எழுதுங்கள்.',
    no_words: 'இந்தச் செய்தியில் சொற்கள் எதுவும் இல்லை, அதனால் தொடக்க வாய்ப்பு மட்டுமே கணக்கில் வந்தது.',
    no_model: 'இன்னும் பயிற்சிச் செய்திகள் இல்லை. “கற்றுக்கொடுங்கள்” பகுதியில் சேருங்கள் அல்லது மாதிரிச் செய்திகளை ஏற்றுங்கள்.',
    need_both: 'குறைந்தது ஒரு ஸ்பேம் மற்றும் ஒரு உண்மையான செய்தியைச் சேருங்கள், இல்லையெனில் வடிகட்டி எப்போதும் ஒரே பதிலைத் தரும்.',
