    even_word: 'இரண்டிலும் சமம்',
    maths_t: 'படிப்படியாக: கணக்கு',
    step_prior: 'படி 1 · தொடக்க வாய்ப்பு (prior). {n} பயிற்சிச் செய்திகளில் {s} ஸ்பேம், {h} உண்மையானவை.',
    prior_line: 'P(ஸ்பேம்) = {s} ÷ {n} = {ps} · P(உண்மை) = {h} ÷ {n} = {ph}',
    step_words: 'படி 2 · ஒவ்வொரு சொல்லுக்கும்: ஸ்பேம் செய்தியில் அது எவ்வளவு வருகிறது, உண்மையானதில் எவ்வளவு? ஒவ்வொரு எண்ணிக்கையுடனும் 1 கூட்டுகிறோம் (Laplace smoothing), அப்போதுதான் ஒரு வகையில் பார்க்காத சொல் முழுப் பெருக்கலையும் பூஜ்ஜியமாக்காது.',
    formula_word: 'P(சொல் | வகை) = (அந்த வகையில் சொல் வந்த தடவைகள் + 1) ÷ (அந்த வகையின் மொத்தச் சொற்கள் + V)',
