    tiny: 'கணினி காட்ட முடியாத அளவு சிறியது (அதனால்தான் உண்மையான வடிகட்டிகள் பெருக்குவதற்குப் பதில் மடக்கைகளைக் கூட்டுகின்றன)',
    step_compare: 'படி 4 · ஒப்பிடுங்கள். இரண்டு மதிப்பெண்களில் ஸ்பேம் மதிப்பெண்ணின் பங்கே இறுதி விடை.',
    final_line: 'P(ஸ்பேம் | செய்தி) = {a} ÷ ({a} + {b}) = {p}',
    final_only: 'P(ஸ்பேம் | செய்தி) = {p}',
    log_note: 'உண்மையான நிரல்கள் பெருக்குவதற்குப் பதில் log மதிப்புகளைக் கூட்டுகின்றன, ஏனெனில் பல சிறிய எண்களைப் பெருக்கினால் சேமிக்க முடியாத அளவு சிறியதாகிவிடும். வெற்றியாளர் மாறுவதில்லை. இந்தச் செய்தியின் மொத்த log-odds: {lo} (நேர்மம் = ஸ்பேம்).',
    unknown_line: 'பயிற்சியில் பார்க்காததால் விடப்பட்டவை: {words}',

    step2: 'கற்றுக்கொடுங்கள்: பயிற்சிச் செய்திகள்',
    step2_hint: 'வடிகட்டி இந்தச் செய்திகளிலிருந்து மட்டுமே கற்கிறது. உங்கள் செய்திகளைச் சேருங்கள், சிலவற்றை நீக்குங்கள், மேலே உள்ள முடிவு உடனே மாறுவதைப் பாருங்கள்.',
