    add_ph: 'செய்தியை எழுதி Enter அழுத்துங்கள்',
    dup_msg: 'இந்தச் செய்தி ஏற்கெனவே பட்டியலில் உள்ளது.',
    max_rows: 'வரம்பு எட்டியது: {n} செய்திகள்.',
    load_samples: 'மாதிரிச் செய்திகள்',
    samples_all: '40 மாதிரிச் செய்திகளும் ஏற்கெனவே பட்டியலில் உள்ளன.',
    confirm_samples: 'விடுபட்ட மாதிரிச் செய்திகளைத் திரும்பக் கொண்டுவரவா? உங்கள் சொந்தச் செய்திகள் அப்படியே இருக்கும்.',
