    export_csv: 'CSV பதிவிறக்கு',
    import_csv: 'CSV ஏற்று',
    csv_hint: 'text, label (spam அல்லது ham) நெடுவரிசைகள் உள்ள CSV கோப்பு. இது Excel அல்லது Google Sheets-இல் திறக்கும்.',
    import_bad: 'இந்தக் கோப்பைப் படிக்க முடியவில்லை. இரண்டு நெடுவரிசைகள் வேண்டும்: text, label (spam / ham).',
    import_ok: '{n} செய்திகள் சேர்க்கப்பட்டன.',
    confirm_import: 'இந்தக் கோப்பின் {n} செய்திகளைப் பயிற்சிச் செய்திகளில் சேர்க்கவா?',
    nothing_export: 'பதிவிறக்க இன்னும் செய்திகள் இல்லை.',
    samples_note: 'மாதிரிச் செய்திகள் செயலியின் மொழியில் தெரியும். நீங்கள் சேர்க்கும் செய்திகள் மொழிபெயர்க்கப்படுவதில்லை.',
    exp_t: 'சோதனை: “வென்றீர்கள்” எப்போதும் ஸ்பேமா?',
    exp_d: 'குழப்பும் செய்தி நண்பரின் உண்மையான செய்தி, ஆனால் அதில் “வாழ்த்துகள்”, “வென்றாய்”, “பரிசு” போன்ற சொற்கள் உள்ளன; வடிகட்டி இவற்றை ஸ்பேமில் மட்டுமே பார்த்துள்ளது. இந்தச் சொற்கள் உள்ள 3 உண்மையான செய்திகளைச் சேர்த்து என்ன நடக்கிறது என்று பாருங்கள்.',
    exp_btn: '3 உண்மையான செய்திகளைச் சேர்',
    exp_before: 'முன்',
    exp_after: 'பின்',
    exp_result: 'குழப்பும் செய்தி ஸ்பேம் ஆக வாய்ப்பு: {a} → {b}. இந்தச் சொற்கள் உண்மையான செய்திகளிலும் வரும் என்று வடிகட்டி கற்றுக்கொண்டது.',
    exp_small: 'குழப்பும் செய்தி ஸ்பேம் ஆக வாய்ப்பு: {a} → {b}. அதிக மாற்றமில்லை. இந்தச் சொற்கள் உள்ள இன்னும் சில உண்மையான செய்திகளைச் சேருங்கள்.',
    undo_exp: 'சோதனையைத் திரும்பப் பெறு',

    step3: 'இது எவ்வளவு நல்லது? நியாயமான சோதனை',
    holdout_label: 'மாதிரிச் செய்திகளில் 25% ஐ சோதனைக்காகத் தனியாக வையுங்கள்; வடிகட்டி அவற்றிலிருந்து ஒருபோதும் கற்காது',
    st_train: 'பயிற்சிச் செய்திகள்',
    st_test: 'சோதனைச் செய்திகள்',
    st_vocab: 'தெரிந்த தனிச் சொற்கள்',
    st_acc: 'சோதனையில் சரி',
    acc_none: 'சோதனைச் செய்திகள் இல்லை. மேலே நியாயமான சோதனையை இயக்குங்கள், அல்லது மாதிரிச் செய்திகளை ஏற்றுங்கள்.',
    cheat_note: 'நியாயமான சோதனை அணைந்துள்ளது, அதனால் வடிகட்டி கற்ற அதே செய்திகளிலேயே சோதிக்கப்படுகிறது, ஒரு மாணவர் தன் வீட்டுப்பாடத்தைத் தானே திருத்துவது போல. மதிப்பெண் உண்மையை விட நன்றாகத் தெரியும்.',
    reshuffle: 'வேறு சோதனைச் செய்திகளைத் தேர்',
    cm_t: 'குழப்ப அணி (confusion matrix)',
