    no_words: 'ఈ మెసేజ్‌లో పదాలు ఏవీ లేవు, అందుకే మొదటి అవకాశం మాత్రమే లెక్కలోకి వచ్చింది.',
    no_model: 'ఇంకా శిక్షణ మెసేజ్‌లు లేవు. “నేర్పండి”లో కొన్ని చేర్చండి లేదా నమూనా మెసేజ్‌లు లోడ్ చేయండి.',
