    acc_none: 'టెస్ట్ మెసేజ్‌లు లేవు. పైన న్యాయమైన టెస్ట్ ఆన్ చేయండి, లేదా నమూనా మెసేజ్‌లు లోడ్ చేయండి.',
    cheat_note: 'న్యాయమైన టెస్ట్ ఆఫ్‌లో ఉంది, కాబట్టి ఫిల్టర్ నేర్చుకున్న మెసేజ్‌లపైనే దాన్ని పరీక్షిస్తున్నాం, విద్యార్థి తన హోంవర్క్ తానే దిద్దుకున్నట్టు. స్కోర్ నిజం కంటే బాగా కనిపిస్తుంది.',
    reshuffle: 'వేరే టెస్ట్ మెసేజ్‌లు ఎంచుకోండి',
