    recall_line: 'Recall {p}: మొత్తం నిజమైన స్పామ్‌లో ఇంత భాగం పట్టుబడింది.',
    mistakes_t: 'వీటిలో తప్పు ఎందుకు జరిగింది? ({n})',
    no_mistakes: 'టెస్ట్ మెసేజ్‌లలో తప్పులు లేవు. కష్టమైన సెట్ కోసం “వేరే టెస్ట్ మెసేజ్‌లు ఎంచుకోండి” నొక్కండి.',
    mistake_line: 'ఫిల్టర్ చెప్పింది {guess}, నిజానికి {real} ({p} స్పామ్).',
    mistake_why: 'ముఖ్యంగా ఈ పదాల వల్ల: {words}.',
    mistake_why_none: 'దీని పదాలు ఏవీ శిక్షణలో లేవు, అందుకే మొదటి అవకాశమే నిర్ణయించింది.',
    see_why: 'లెక్క చూడండి',

    peek_t: 'లోపలికి తొంగి చూడండి: పదాల లెక్కలే మొత్తం మోడల్',
    peek_note: 'శిక్షణ అంటే లెక్కించడమే. ఫిల్టర్‌కు తెలిసినదంతా ఈ పట్టికలోనే ఉంది.',
