    exp_t: 'പരീക്ഷണം: “നേടി” എപ്പോഴും സ്പാം ആണോ?',
    exp_d: 'കുഴപ്പിക്കുന്ന മെസേജ് ഒരു സുഹൃത്തിന്റെ യഥാർഥ മെസേജാണ്, പക്ഷേ അതിൽ “അഭിനന്ദനങ്ങൾ”, “നേടി”, “സമ്മാനം” പോലുള്ള വാക്കുകളുണ്ട്; ഫിൽറ്റർ ഇവ സ്പാമിൽ മാത്രമേ കണ്ടിട്ടുള്ളൂ. ഈ വാക്കുകളുള്ള 3 യഥാർഥ മെസേജുകൾ ചേർത്ത് എന്ത് സംഭവിക്കുന്നു എന്ന് കാണൂ.',
    exp_btn: '3 യഥാർഥ മെസേജുകൾ ചേർക്കൂ',
    exp_before: 'മുമ്പ്',
    exp_after: 'ശേഷം',
    exp_result: 'കുഴപ്പിക്കുന്ന മെസേജിന്റെ സ്പാം സാധ്യത: {a} → {b}. ഈ വാക്കുകൾ യഥാർഥ മെസേജുകളിലും വരുമെന്ന് ഫിൽറ്റർ പഠിച്ചു.',
    exp_small: 'കുഴപ്പിക്കുന്ന മെസേജിന്റെ സ്പാം സാധ്യത: {a} → {b}. വലിയ മാറ്റമില്ല. ഈ വാക്കുകളുള്ള കുറച്ച് യഥാർഥ മെസേജുകൾ കൂടി ചേർക്കൂ.',
