    inside_t: 'ഉള്ളിൽ എന്താണ് നടക്കുന്നത്?',
    in1_t: 'ഇത് വാക്കുകൾ മാത്രം എണ്ണുന്നു',
    in1: 'പരിശീലനം എന്നാൽ എണ്ണൽ: ഓരോ വാക്കും സ്പാം മെസേജുകളിൽ എത്ര തവണ, യഥാർഥത്തിൽ എത്ര തവണ? “ലോട്ടറി” സ്പാമിൽ കൂടുന്നു, “ഹോംവർക്ക്” യഥാർഥത്തിൽ.',
    in2_t: 'Bayes നിയമം',
    in2: 'പുതിയ മെസേജിന്, ഓരോ വിഭാഗത്തിന്റെയും തുടക്ക സാധ്യതയെ ആ വിഭാഗത്തിലെ ഓരോ വാക്കിന്റെയും സാധ്യത കൊണ്ട് ഗുണിക്കുന്നു. വലിയ ഫലമുള്ളത് ജയിക്കുന്നു. ഇതാണ് Naive Bayes, ആദ്യത്തെ ഇമെയിൽ സ്പാം ഫിൽറ്ററുകളുടെ രീതി.',
    formula: 'P(സ്പാം | മെസേജ്) ∝ P(സ്പാം) × P(വാക്ക്₁ | സ്പാം) × P(വാക്ക്₂ | സ്പാം) × …',
    in3_t: 'Laplace smoothing: +1 എന്ന സൂത്രം',
    in3: 'ഒരു വാക്ക് ഒരു വിഭാഗത്തിൽ ഒരിക്കലും കണ്ടില്ലെങ്കിൽ അതിന്റെ സാധ്യത 0 ആകുകയും മുഴുവൻ ഗുണനഫലവും 0 ആകുകയും ചെയ്യും. ഓരോ എണ്ണത്തിലും 1 കൂട്ടിയാൽ (ഭിന്നത്തിന്റെ താഴെ V കൂട്ടിയാൽ) ഓരോ സാധ്യതയും പൂജ്യത്തിന് അൽപം മുകളിൽ നിൽക്കും.',
    in4_t: 'ലോഗ് എന്തിന്?',
    in4: '0.003 പോലുള്ള ഇരുപത് സംഖ്യകൾ ഗുണിച്ചാൽ 0.000000000000000000000000000001 പോലെ എന്തെങ്കിലും കിട്ടും. കമ്പ്യൂട്ടറുകൾക്ക് ഇത്ര ചെറിയ സംഖ്യകൾ നഷ്ടപ്പെടും, അതിനാൽ യഥാർഥ ഫിൽറ്ററുകൾ log മൂല്യങ്ങൾ കൂട്ടുന്നു. വിജയി മാറില്ല.',
    in5_t: '“Naive” (നിഷ്കളങ്കം) എന്തുകൊണ്ട്?',
    in5: 'ഇത് ഓരോ വാക്കിനെയും വെവ്വേറെ കാണുന്നു, ക്രമവും അർഥവും ശ്രദ്ധിക്കുന്നില്ല. “മത്സരം ജയിച്ചു”, “ലോട്ടറി ജയിച്ചു” രണ്ടിലും “ജയി” മാത്രം. അതുകൊണ്ടാണ് കുഴപ്പിക്കുന്ന മെസേജ് ഇതിനെ കബളിപ്പിക്കുന്നത്, പലതരം ഉദാഹരണങ്ങൾ സഹായിക്കുന്നതും.',
    in6_t: 'യഥാർഥ സ്പാം ഫിൽറ്ററുകൾ',
    in6: 'Gmail-ഉം WhatsApp-ഉം ഇതേ ആശയവും അതിലേറെയും ഉപയോഗിക്കുന്നു: അയച്ചയാളുടെ ചരിത്രം, ലിങ്കുകൾ, ചിത്രങ്ങൾ, വലിയ ന്യൂറൽ നെറ്റ്‌വർക്കുകൾ. പക്ഷേ പാഠം ഒന്നുതന്നെ: ഫിൽറ്റർ അത് പഠിച്ച ഉദാഹരണങ്ങളോളം മാത്രമേ നല്ലതാകൂ.',

    help_t: 'എങ്ങനെ ഉപയോഗിക്കാം · ക്ലാസിനുള്ള ആശയങ്ങൾ',
    tip1: '“മെസേജ് പരിശോധിക്കൂ” എന്നതിൽ ഏത് മെസേജും എഴുതൂ. തീരുമാനവും വാക്ക് ബാറുകളും ഘട്ടം ഘട്ടമായ കണക്കും എഴുതുമ്പോൾ തന്നെ മാറും.',
    tip2: '“ഘട്ടം ഘട്ടമായി: കണക്ക്” തുറന്ന്, “ഉള്ളിലേക്ക് നോക്കൂ” എണ്ണങ്ങൾ ഉപയോഗിച്ച് ഒരു ഭിന്നം കൈകൊണ്ട് പരിശോധിക്കൂ. ഇത് CBSE 10-ാം ക്ലാസ് AI evaluation യൂണിറ്റിനും 11–12 Naive Bayes വിഷയത്തിനും ചേരുന്നു.',
    tip3: 'ക്ലാസ് പ്രവർത്തനം: രണ്ട് ടീമുകൾ. ടീം A ഫിൽറ്റർ സ്പാം എന്ന് പറയുന്ന 5 യഥാർഥ മെസേജുകൾ എഴുതട്ടെ; ടീം B രക്ഷപ്പെടുന്ന 5 സ്പാം എഴുതട്ടെ. അവ പരിശീലന മെസേജുകളിൽ ചേർത്ത് ഏത് ടീമിന്റെ സൂത്രം പ്രവർത്തിക്കാതാകുന്നു എന്ന് കാണൂ.',
